const LOTES=[{"id":"ebserh2025-tecnico","cargo":"Técnico em Enfermagem, Grupo 15, Tipo 1","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/grupo-15-tecnico-em-enfermageme3cnmgp15-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ebserrhassistencial2024_gabarito_definitivo.pdf","itens":[{"numero":1,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Assinale a frase em que não há a presença de um interlocutor.","alternativas":["Vamos, crianças, silêncio na classe!","Eu estou te dizendo que a festa será hoje!","Outras informações, na secretaria, por favor!","Por favor, não fumem!","Vocês, João e Pedro, vão passear?"],"correta":"C"},{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Observe o seguinte texto argumentativo: “Os médicos algumas vezes não respeitam seu horário de trabalho fixado na porta do posto médico. Ontem fui consultar o médico de plantão, mas ele estava ausente!” Nesse caso, a argumentação do emissor utiliza","alternativas":["uma comparação.","um exemplo.","uma explicação.","um apelo à inteligência.","um apelo à emoção"],"correta":"B"},{"numero":3,"disciplina":"Língua Portuguesa","assunto":"Pontuação","enunciado":"Assinale a frase em que, comparativamente, as reticências mostram a expressão de uma emoção intensa.","alternativas":["O quadro não é ... um pouco ... como dizer?","Mas a barata ... a barata ... você a matou?","Quem diria...","Você já sabe, né? O casamento dele...","Comprei o carro barato... barato .."],"correta":"B"},{"numero":4,"disciplina":"Língua Portuguesa","assunto":"Funções da Linguagem","enunciado":"Assinale a frase que mostra um termo que indica a participação pessoal do autor na mensagem da frase.","alternativas":["A população aplaudiu a inauguração do mercado.","Os impostos sobre a água não aumentarão.","O Rio, como São Paulo, enfrenta problemas.","O acusado foi, felizmente, preso.","As máquinas interditaram a pista"],"correta":"D"},{"numero":5,"disciplina":"Língua Portuguesa","assunto":"Tempos, Modos e Vozes Verbais","enunciado":"Assinale a frase que não mostra uma ordem de forma direta ou indireta.","alternativas":["Tente não gastar todo o seu dinheiro.","Lembre-me daqui a dois dias.","Que ela venha aqui amanhã de manhã.","A chuva vai continuar por todo o dia.","Tome um comprimido a cada dia"],"correta":"D"},{"numero":6,"disciplina":"Língua Portuguesa","assunto":"Pontuação","enunciado":"A interrogação direta numa frase é a que leva a uma resposta de sim ou não. Assinale a frase que está nesse caso.","alternativas":["Será que vai chover no final de semana?","Quando haverá novas eleições?","Como ele conseguiu essa proeza?","Onde fica a nova agência do banco?","Por que tudo está tão caro?"],"correta":"A"},{"numero":8,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"Assinale a frase em que a colocação do pronome oblíquo está correta.","alternativas":["Me mostraram a prova do crime.","Deram-me três dias de prazo.","Não deu-me a menor importância.","Quem viu-me fazer isso?","Ninguém observou-me durante a corrida"],"correta":"B"},{"numero":9,"disciplina":"Língua Portuguesa","assunto":"Pontuação","enunciado":"Assinale a frase cuja pontuação está correta.","alternativas":["A verdade, como todos sabem incomoda.","Você Paulo, me deve um grande favor.","Eis a verdade: nada dura a vida toda.","Eu, cumpri o meu dever.","Nós, graças a Deus, estamos, bem"],"correta":"C"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Ortografia e Acentuação","enunciado":"Assinale o vocábulo que mostra correta grafia.","alternativas":["analizar.","democratisar.","concretizar.","gazeificar.","civilisar. Legislação EBSERH"],"correta":"C"},{"numero":11,"disciplina":"Legislação da EBSERH","assunto":"Regimento Interno","enunciado":"O Regulamento de Pessoal da Ebserh disciplina, em âmbito geral, os direitos, os deveres, as obrigações e as penalidades aplicáveis aos integrantes do quadro de pessoal da Ebserh, de suas filiais e das demais unidades descentralizadas. Com base em seus conhecimentos sobre o Regulamento de Pessoal da Ebserh, avalie as afirmativas a seguir. I. É vedado ao empregado efetuar ressarcimento de valores pela utilização de equipamentos da empre sa, para uso pessoal, na forma regulada em norma específica. II. É direito do colaborador organizar ou participar de quaisquer atividades político-partidárias nas dependências da Ebserh. III. Os cargos em comissão e as funções gratificadas constituem cargos de confiança e caracterizam -se por atividades de direção, assessoramento ou chefia. Está correto apenas o que se afirma em","alternativas":["III.","I e II.","I e III.","II e III.","II."],"correta":"A"},{"numero":12,"disciplina":"Legislação da EBSERH","assunto":"Lei 12.550/2011","enunciado":"Conforme a Lei Federal nº 12.550, de 15 de dezembro de 2011, avalie as afirmativas a seguir acerca da regulamentação da Ebserh. I. A Ebserh, respeitado o princípio da autonomia universitária, poderá prestar os serviços relacionados às suas competências mediante contrato com as instituições federais de ensino ou instituições congêneres. II. A Ebserh será administrada por um Conselho de Administração, com funções deliberativas, e por uma Diretoria Executiva, e contará, ainda, com um Conselho Fiscal e um Conselho Consultivo. III. O regime de pessoal pe rmanente da Ebserh será o da Consolidação das Leis do Trabalho. Está correto o que se afirma em","alternativas":["I e II apenas.","II e III, apenas.","II, apenas.","I e III, apenas.","I, II e III"],"correta":"E"},{"numero":15,"disciplina":"Legislação da EBSERH","assunto":"Ética Institucional","enunciado":"O Código de Ética e Conduta da Ebserh apresenta os princípios e os valores requeridos de seus colaboradores. Ele é o norteador principiológico de ações, buscando as segurar, em um patamar superior de ética e valores, a todas as categorias e níveis hierárquicos, uma conduta íntegra no relacionamento com pacientes e seus familiares, com colegas, com fornecedores e com o público em geral. Nesse sentido, trata -se de um do cumento balizador das condutas pessoais e profissionais de todos os empregados da Ebserh, independentemente do cargo ou da função que ocupem. Assinale a afirmativa correta acerca dos ditames do Código de Ética e Conduta da Ebserh.","alternativas":["Os colaboradores em cargos de chefia deverão contribuir para o estabelecimento e a manutenção de um ambiente de trabalho em que prevaleçam a cooperação, a eficiência, a dedicação, a iniciativa, a justiça, a responsabilidade, a transparência e a urbanidade.","A Ebserh buscará adotar medidas para que haja distinção de tratamento entre as pessoas, com respeito à hierarquia e ao desempenho das competências de cada um, em conformidade com os princípios e valores fundamentais.","É vedado ao colaborador atuar, com ganho financeiro ou não, em conflito com o desenvolvimento das atividades da organização.","É direito do colaborador alegar desconhecimento deste Código para tentar defender-se em caso de cometimento de infração.","Os conselheiros e diretores da Ebserh devem se comprometer no sentido de não serem coniventes com qualquer infração a este Código, bem como aos demais atos normativos da empresa. Políticas Públicas de Saúde e Educação"],"correta":"C"},{"numero":16,"disciplina":"Legislação do SUS","assunto":"Política Nacional de Promoção da Saúde","enunciado":"A Portaria GM/MS nº 230, de 7 de março de 2023, institui o Programa Nacional de Equidade de Gênero, Raça e Valorização das Trabalhadoras no Sistema Único de Saúde (SUS). Avalie se as diretrizes da referida Portaria incluem: I. transversalizar os princípios do Programa Nacional de Equidade de Gênero e Ra ça e Valorização das Trabalhadoras no SUS para que estejam presentes nas demais políticas públicas; II. articular, no âmbito federal, a definição de estratégias de equidade de gênero e raça no trabalho na área da saúde; III. fomentar programas de prevenção e combate ao assédio moral e sexual no trabalho compreendendo a dimensão de gênero e raça. Está correto o que se afirma em","alternativas":["I e II, apenas.","I e III, apenas.","III, apenas","II e III, apenas.","I, II e III."],"correta":"B"},{"numero":17,"disciplina":"Legislação do SUS","assunto":"Controle Social no SUS","enunciado":"A Resolução CNS nº 453, de 10 de maio de 2012, aprova diretrizes para a instituição, a reformulação, a reestruturação e o funcionamento dos Conselhos de Saúde. De acordo com essa Resolução, o Conselho de Saúde será composto por representantes de entidades, instituições e movimentos representativos de usuários, de entidades representativas de trabalhadores da área da saúde, do governo e de entidades representativas de prestadores de serviços de saúde, sendo o seu presidente eleito entre os membros do Conselho, em reunião plenária. A referida Resolução preconiza que, de acordo com o que propõem as Resoluções nº 33/92 e nº 333/03 do CNS e de acordo com as Recomendações da 10ª e da 11ª Conferências Nacionais de Saúde, a seguinte distribuição de número de conselheiros está correta:","alternativas":["15% de representantes sindicais.","30% de entidades e movimentos representativos de usuários.","40% de representação de prestadores de serviços privados conveniados, ou sem fins lucrativos.","50% de representantes do governo.","25% de entidades representativas dos trabalhadores da área de saúde"],"correta":"E"},{"numero":18,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"A Resolução da Diretoria Colegiada da Agência Nacional de Vigilância Sanitária (RDC nº 63, de 25 de novembro de 2011) estabelece os requisitos de boas práticas de funcionamen to para os serviços de saúde e os padrões para o funcionamento dos serviços de atenção à saúde fundamentados na qualificação, na humanização da atenção e da gestão e na redução e no controle de riscos aos usuários e ao meio ambiente. Conforme os ditames da RDC nº 63, de 25 de novembro de 2011, assinale a afirmativa correta.","alternativas":["Este Regulamento Técnico se aplica aos serviços de saúde no país, sejam eles públicos, filantrópicos, civis ou militares, incluindo aqueles que exercem ações de ensino e pesquisa.","Os conceitos de Garantia da Qualidade e Boas Práticas de Funcionamento (BPF) são independentes, estando descritos nesta resolução de forma a individualizar a sua importância para o funcionamento dos serviços de saúde.","O serviço de saúde deve ser capa z de ofertar serviços, dentro dos padrões de qualidade exigidos, de forma independente dos requisitos das legislações e dos regulamentos vigentes.","As reclamações sobre os serviços oferecidos devem ser examinadas e registradas, e as causas dos desvios d a qualidade, investigadas e documentadas, devendo ser tomadas medidas com relação aos serviços que apresentem desvio da qualidade e adotadas as providências no sentido de prevenir reincidências.","Os dados que compõem o prontuário pertencem ao serviço de saúde e devem estar permanentemente disponíveis aos pacientes ou aos seus representantes legais e à autoridade sanitária quando necessário"],"correta":"D"},{"numero":20,"disciplina":"Legislação do SUS","assunto":"Atenção Primária e PNAB","enunciado":"A Política Nacional de Atenção Básica (PNAB) é resultado da experiência acumulada pelo conjunto de atores envolvidos historicamente com o desenvolvimento e a consolidação do Sistema Único de Saúde (SUS), como movimentos sociais, usuários, trabalhadores e gestores das três esferas de governo. Avalie se as competências das Secretarias Estaduais de Saúde e do Distrito Federal incluem: I. prestar apoio institucional aos gestores dos Estados, ao Distrito Federal e aos Municípios no processo de qualificação e de consolidação da atenção básica; II. estabelecer, de forma tripartite, as diretrizes nacionais e disponibilizar instrumentos técnicos e pedagógicos que facilitem o processo de gestão, formação e educação permanente dos gestores e profissionais da atenção básica; III. consolidar, analisar e transferir para o Ministério da Saúde os arquivos dos sistemas de informação enviados pelos Municípios de acordo com os fluxos e prazos estabelecidos para cada sistema. Está correto o que se afirma em","alternativas":["III, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III."],"correta":"A"},{"numero":21,"disciplina":"Legislação do SUS","assunto":"Financiamento do SUS e LC 141/2012","enunciado":"A Lei Complementar nº 141/2012 dispõe, em seu Capítulo III, sobre a aplicação de recursos em ações e serviços públicos de saúde. Com base na lei, avalie as afirmativas a seguir acerca dos recursos mínimos. I. A União aplicará, anualmente, em ações e serviços públicos de saúde, o montante correspondente ao valor empenhado no exercício financeiro anterior, apurado nos termos desta Lei Complementar, acrescido de, no mínimo, o percentual correspondente à variação nominal do Produto Interno Bruto (PIB) ocorrida no ano anterior ao da Lei Orçamentária Anual (LOA). II. Em caso de variação negativa do PIB, o valor de que trata o item I acima poderá ser reduzido, em termos nominais, de um exercício financeiro para o outro. III. Os Estados, o Distrito Federal e os Municípios deverão observar o disposto nas respectivas Constituições ou Leis Orgânicas sempre que os percentuais nelas estabelecidos forem superiores aos fixados nesta Lei Complementar para a aplicação em ações e serviços públicos de saúde. Está correto o que se afirma em","alternativas":["I e II, apenas.","I, II e III.","II e III, apenas.","I e III, apenas","III, apenas"],"correta":"D"},{"numero":22,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"As Redes de Atenção à Saúde (RAS) são c onjuntos de serviços de saúde que se organizam para garantir a integralidade do cuidado e o acesso dos usuários do Sistema Único de Saúde (SUS). O objetivo é que cada pessoa seja atendida pelo serviço mais adequado à sua situação de saúde, de forma contínua, integral, de qualidade e humanizada. A Portaria de Consolidação GM/MS nº 3/2017 apresenta os fundamentos para que as Redes de Atenção à Saúde sejam efetivadas de forma eficiente e com qualidade. Acerca do tema, considere a sentença a seguir. Os serviço s de menor densidade tecnológica, como os das Unidades Básicas de Saúde (UBS), são ofertados de forma dispersa, uma vez que se beneficiam menos dela, enquanto os serviços com maior densidade tecnológica se beneficiam mais. A sentença se refere à seguinte diretriz/estratégia:","alternativas":["economia de escala.","suficiência e qualidade.","disponibilidade de recursos.","integração vertical.","integração horizontal"],"correta":"A"},{"numero":23,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"A Portaria GM/MS nº 1.526, de 11 de outubro de 2023 altera as Portarias de Consolidação GM/MS nº 2, nº 3 e nº 6, de 28 de setembro de 2017, para dispor sobre a Política Nacional de Atenção Integral à Saúde da Pessoa com Deficiência (PNAISPD) e Rede de Cuidados à Pessoa com Deficiência (RCPD) no âmbito do Sistema Único de Saúde (SUS). A PNAISPD tem por objetivo promover e proteger a saúde da pessoa com deficiência, por meio da ampliação do acesso ao cuidado integral no âmbito do SUS, em articulação com as demais políticas e ações intersetoriais, contribuindo para sua a utonomia, qualidade de vida e inclusão social, bem como prevenindo diferentes agravos à saúde em todos os ciclos de vida. Avalie se os princípios ou as diretrizes estabelecidos pela Política Nacional de Atenção Integral à Saúde da Pessoa com Deficiência (PNAISPD) incluem: I. Gestão federativa das ações de saúde voltadas à pessoa com deficiência. II. Estímulo à isonomia dos cuidados com as pessoas com deficiência. III. Promoção da acessibilidade em suas diferentes dimensões. Está correto o que se apresenta em","alternativas":["I, II e III.","I e II, apenas.","I e III, apenas.","II, apenas.","III, apenas"],"correta":"E"},{"numero":24,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"A Política Nacional de Vigilância em Saúde (PNVS) é um guia que orienta as ações de vigilância em saúde no Brasil. A PNVS define os princípios, as diretrizes e as estratégias para o desenvolvimento da vigilância em saúde, sob a gestão do SUS. Em relação à PNVS, é correto afirmar que","alternativas":["é uma política pública de Estado e função essencial do SUS, tendo caráter universal, horizontal e orientador do modelo de atenção nos territórios, sendo a sua gestão de responsabilidade exclusiva do Poder Público.","incide sobre todos os níveis e todas as formas de atenção à saúde, abrangendo os serviços de saúde públicos, além de estabelecimentos r elacionados à produção e circulação de bens de consumo e tecnologias que, direta ou indiretamente, se relacionem com a saúde.","compreende a articulação dos saberes, dos processos e das práticas relacionados à vigilância epidemiológica, vigilância em saúde ambiental, vigilância em saúde do trabalhador e vigilância sanitária e alinha -se com o conjunto de políticas de saúde no âmbito do SUS, considerando a transversalidade das ações de vigilância em saúde sobre a determinação do processo saúde-doença.","tem como finalidade definir os princípios, as diretrizes e as estratégias a serem observados pela esfera federal de gestão do SUS para o desenvolvimento da vigilância em saúde, objetivando a promoção e a proteção da saúde e a prevenção de doenças e agravos.","a análise de situação de saúde e as ações laboratoriais são atividades horizontais e essenciais no processo de trabalho da Vigilância em Saúde."],"correta":"C"},{"numero":25,"disciplina":"Legislação do SUS","assunto":"Vigilância em Saúde","enunciado":"No Brasil, a vigilância de eventos adversos relacionados ao uso dos produtos que estão sob a vigilância sanitária inclui o monitoramento do uso desses produtos e tem como objetivo fundamental a detecção precoce de problemas relacionados a esse uso para desencadear as medidas pertinentes para que o risco seja interrompido ou minimizado. Em relação ao tema, avalie as afirmativas a seguir acerca do Sistema de Notificação de Eventos Adversos no Brasil. I. A notificação do cidadão é obrigatória, os dados sobre os notificadores são confidenciais, obedecidos os dispositivos legais, e sua guarda é de responsabilidade do Sistema Nacional de Vigilância Sanitária (SNVS). II. As notificações estarão acessíveis à unidade de saúde envolvida no relato para o devido tratamento. III. A linguagem a ser utilizada na notificação deve ser adaptada e amigável, de forma a promover a participação dos diferentes públicos. Está correto o que se afirma em","alternativas":["I, II e III.","I e III, apenas.","II e III, apenas.","I e II, apenas.","III, apenas"],"correta":"C"},{"numero":26,"disciplina":"Saúde Coletiva I","assunto":"Educação Permanente em Saúde","enunciado":"A Política Nacional de Educação Permanente em Saúde (PNEPS - SUS) reafirma o compromisso com a universalidade, a equidade, a integralidade e a efetiva participação popular no SUS e propõe uma prática político -pedagógica que perpassa as ações voltadas para a promoção, proteção e recuperação da saúde, a partir do diálogo entre a diversidade de saberes, valorizando os saberes populares, a ancestralidade, o incentivo à produção individual e coletiva de conhecimentos e a inserção destes no SUS. Conforme a Portaria nº 2.761, de 19 de novembro de 2013, compete ao Ministério da Saúde","alternativas":["estabelecer estratégias e ações de planejamento, monitoramento e avaliação da PNEPS -SUS construídas de forma participativa com atores da sociedade civil implicados com a Educação Popular em Saúde.","estabelecer e stratégias e ações de planejamento, monitoramento e avaliação da PNEPS -SUS construídas no âmbito do Comitê Nacional de Educação Popular em Saúde (CNEPS).","garantir a inclusão da PNEPS -SUS nos respectivos Planos Municipais Plurianuais de Saúde, em conson ância com as realidades, demandas e necessidades locais.","estabelecer e implementar estratégias e ações de planejamento, monitoramento e avaliação da PNEPS -SUS construídas de forma participativa com atores da sociedade civil implicados com a Educação Popular em Saúde.","garantir financiamento complementar aos Municípios para a implantação da PNEPS-SUS"],"correta":"B"},{"numero":27,"disciplina":"Legislação do SUS","assunto":"Decreto 7.508/2011","enunciado":"O Decreto nº 7.508, de 28 de junho de 2011, regulamenta a Lei nº 8.080, de 19 de setembro de 1990, que trata do Sistema Único de Sa úde (SUS). O referido decreto dispõe sobre a organização do SUS, o planejamento da saúde, a assistência à saúde e a articulação interfederativa. Com base nesse decreto, em relação ao planejamento da saúde, é correto afirmar que","alternativas":["o planejamento da saúde em âmbito municipal deve ser realizado de maneira regionalizada, a partir das necessidades dos Municípios, considerando o estabelecimento de metas de saúde.","o Mapa da Saúde será utilizado na identificação das necessidades de saúde e orientará o planejamento integrado dos Municípios, contribuindo para o estabelecimento de metas de saúde.","o planejamento da saúde é obrigatório para os entes privados e será indutor de políticas para a iniciativa da saúde pública.","o processo de planejamento da saúde será ascendente e integrado, do nível local até o federal, ouvidos os respectivos Conselhos de Saúde, compatibilizando-se as necessidades das políticas de saúde com a disponibilidade de recursos financeiros.","compete à Comissão Intergestores Tripartite pactuar as etapas do processo e os prazos do planejamento municipal em consonância com os planejamentos municipal, estadual e nacional"],"correta":"D"},{"numero":28,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"Conforme a Constituição Federal de 1988, no seu Art. 194: A seguridade so cial compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinadas a assegurar os direitos relativos à saúde, à previdência e à assistência social. Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social... Avalie se os objetivos que baseiam a organização da seguridade social incluem: I. Irredutibilidade do valor dos benefícios. II. Universalidade da cobertura e do atendimento. III. Caráter democrático e descentralizado da Administração. IV. Uniformidade e equivalência dos benefícios e serviços às populações urbanas e rurais. Estão corretos os itens","alternativas":["I e II, apenas.","III e IV, apenas.","I, II e III, apenas.","II, III e IV, apenas.","I, II, III e IV."],"correta":"E"},{"numero":29,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"A RDC nº 63, de 25 de novembro de 2011, objetiva estabelecer requisitos de Boas Práticas de Funcionamento (BPF) para os serviços de saúde, fundamentados na qualificação, na humanização da atenção e gestão e na redução e no control e de riscos aos usuários e meio ambiente. A referida RDC define que o serviço de saúde deve estabelecer estratégias e ações voltadas para a segurança do paciente. De acordo com essa RDC, as estratégias voltadas para a segurança do paciente incluem as elencadas a seguir, à exceção de uma . Assinale-a.","alternativas":["Implementação de mecanismos de identificação do paciente.","Orientações para limitar a participação do paciente na assistência prestada.","Ações de prevenção e controle de eventos adversos relacionados à assistência à saúde.","Implementação de m ecanismos para a prevenção de quedas dos pacientes.","Orientações para a higienização das mãos"],"correta":"B"},{"numero":30,"disciplina":"Legislação do SUS","assunto":"Direitos dos Usuários do SUS","enunciado":"A Resolução CNS nº 553, de 9 de agosto de 2017, dispõe sobre a carta dos direitos e deveres da pessoa usuária da saúde. Conforme a sua terceira diretriz, toda pessoa tem direito ao atendimento inclusivo, humanizado e acolhedor, realizado por profissionais q ualificados, em ambiente limpo, confortável e acessível. Avalie, com base nessa diretriz, as afirmativas a seguir: I. Nos serviços de saúde, será dada igual visibilidade aos direitos e deveres das pessoas usuárias e das pessoas que trabalham no serviço de saúde. II. A Rede de Serviços do SUS utilizará as tecnologias disponíveis para facilitar o agendamento de procedimentos nos serviços de saúde em todos os níveis de complexidade. III. Os serviços de saúde serão organizados de acordo com a demanda da populaç ão, e não limitados por produção ou quantidades de atendimento predeterminados. Está correto o que se afirma em","alternativas":["I, II e III.","I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas."],"correta":"A"},{"numero":31,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"O exercício de enfermagem é regulamentado pela Lei nº 7498/86 e pelo Decreto nº 94.406/87 do Cofen. De acordo com esses dispositivos legais, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O Art. 10 do Decreto citado dispõe que o técnico de enfermagem exerce atividades auxiliares, de nível médio, atribuídas à equipe de Enfermagem. ( ) Cabe ao técnico de enfermagem assistir ao enfermeiro na prevenção e no controle sistemático da infecção hospitalar. ( ) De acordo com o Art. 14 do Decreto citado, é privativo do enfermeiro o cumprimento do Código de Deontologia da Enfermagem. ( ) A partir de 2022, a Lei do Exercício Profissional da Enfermagem sofreu alteração para contempl ar condições adequadas de repouso durante todo o horário de trabalho. No entanto, essa alteração abrange, apenas, as instituições de saúde públicas. As afirmativas são, respectivamente,","alternativas":["F – V – F – V.","V – F – F – V.","F – V – V – F.","V – V – F – F.","V – F – V – F"],"correta":"D"},{"numero":32,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"O Código de Ética Profissional é um instrumento legal que deve ser de amplo conhecimento e dominado pela equipe de enfermagem, pois, entre outras funções, orienta a conduta e abrange os direitos e deveres dos profissionais. Tomando como base a Resolução Cofen nº 564/2017, que aprova o novo Código de Ética dos Profissionais de Enfermagem e seu anexo, é correto afirmar que","alternativas":["é proibido à equipe de enfermagem cooperar em prática destinada a interromper a gestação, mas em casos permitidos por lei a atuação é obrigatória.","entre as penalidades a serem impostas ao técnico de enfermagem, em caso de infração, estão a advertência verbal, a suspensão ou cassação do direito ao exercício profissional. As multas são impostas apenas aos enfermeiros, em razão do piso salarial.","no âmbito da assistência de enfermagem, um dano que provoque debilidade temporária de membro, sentido ou função na pessoa é considerada uma infração grave.","a c omunicação formal ao Cofen e ao Coren de fatos que infrinjam dispositivos éticos -legais ocorridos na equipe cabe ao enfermeiro e não ao técnico de enfermagem.","é proibido negar assistência de enfermagem em situações de epidemia, desastre e catástrofe, desde que não ofereçam risco à integridade física do profissional."],"correta":"E"},{"numero":33,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"O papilomavírus humano (HPV) é responsável por uma infecção sexualmente transmissível (IST) muito comum, relacionada ao câncer de colo de útero e outros tumores, tanto e m mulheres quanto em homens. A vacina HPV4-recombinante está disponível no SUS. Essa disponibilidade deve ser divulgada, e a população deve ser estimulada a aderir a seu uso. Sobre essa vacina, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A vacina HPV4-recombinante é aplicada em meninos a partir de 12 anos de idade e em meninas a partir da menarca. ( ) Para vítimas de abuso sexual, de 9 a 14 anos, a recomendação é de duas doses. ( ) Para pessoas de 15 a 45 anos, a recomendação é de três doses, considerando o histórico vacinal contra o HPV. ( ) Para os adolescentes não vacinados de 15 a 19 anos de idade, estratégias de resgate para a vacinação de dose única devem ser realizadas. As afirmativas são, respectivamente,","alternativas":["V – V – F – V.","F – V – V – F.","F – V – V – V.","V – F – F – V.","F – F – V – F"],"correta":"C"},{"numero":34,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Infecções Sexualmente Transmissíveis (IST) são causadas por diferentes micro-organismos. No Sistema Único de Saúde (SUS), há profissionais, métodos diagnósticos e tratamentos disponíveis, além de medidas de prevenção. Ao realizar um trabalho de educação em saúde sobre IST, o técnico de enfermagem deve incluir a seguinte orientação:","alternativas":["Se a mulher detectar presença de corrimento vaginal, deve observar a consistência, a cor, as alterações no odor, a presença de prurido e/ou irritação local para que possa fazer um relato objetivo e preciso na consulta de enfermagem e/ou médica para a avaliação de infecção vaginal.","Adolescentes com vida sexualmente ativa podem receber preservativos externos (camisinhas) gratuitamente nas Unidades Básicas de Saúde, mediante apresentação do cartão do SUS e de um documento com foto.","No caso dos preservativos externos, a camisinha masculina é descartável e de uso único, mas a feminina pode ser reutilizada desde que seja adequadamente higienizada.","Gestação e lactação são condições que contraindicam a imunização contra a hepatite B.","A sífilis é uma doença grave e deve ser prevenida com medidas comportamentais eficazes, pois é de difícil tratamento em virtude da resistência do T. pallidum aos antibióticos existentes"],"correta":"A"},{"numero":35,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"No conjunto de Doenças e Agravos Não Transmissíveis se consideram os acidentes e as violências. No atendimento integral à saúde da criança e do adolescente em situação de violência, analise as afirmativas a seguir. I. Como membro da equipe de saúde, o técnico de enfermagem pode contribuir para o fortalecimento da resiliência por meio do estabelecimento de vínculos com as crianças e os adolescentes atendidos e suas famílias. II. A sala de vacina é um local de atuação em que o técnico de enfermagem pode observar a existência de sinais e sintomas que possam ser resultantes de uma situação de violência contra a criança e/ou adolescentes. III. Enurese, encoprese, comportamentos obsessivos ou atitudes compulsivas são sinais de violência em crianças de 5 a 9 anos e adolescentes de 10 a 19 anos. Está correto o que se afirma em","alternativas":["II, apenas.","I e II, apenas.","II e III, apenas.","I e III, apenas.","I, II, III"],"correta":"E"},{"numero":36,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Na sala de vacina, o técnico de enfermagem atua na avaliação da caderneta vacinal, como também nas orientações sobre a finalidade dos imunizantes e nos cuidados pós-vacina. Ao receber um usuário idoso, o técnico deve lembrar que","alternativas":["a vacina hepatite B (HB -recombinante) é indicada até os 59 anos, não devendo, portanto, ser administrada em pessoas com 60 anos ou mais.","a administração da vacina febre amarela em pessoas com 60 anos ou mais deverá considerar a relação risco x benefício da vacinação.","pessoas idosas só podem ser vacinadas mediante prescrição de um médico gerontólogo.","a vacina tríplice viral é administrada em duas doses, com intervalo de 30 dias.","apesar de poder ser aplicada, a vacina dTpa não é recomendada, pois idosos não são susceptíveis a contrair coqueluche"],"correta":"B"},{"numero":37,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Na atenção integral à saúde do homem, a prevenção do câncer de pênis é uma das medidas de promoção à saúde que contribui para a qualidade de vida do homem. Do conjunto de cuidados de enfermagem voltados a este grupo populacional, recomenda -se que, no plano de orientações, o técnico de enfermagem explique que","alternativas":["a postectomia (circuncisão) pode ser necessária quando o prepúcio (pele que encobre a glande) não permite a higienização de maneira correta.","o tabagismo está associado ao aumento no risco de vários tipos de cânceres, mas não ao de pênis.","adolescentes (10 a 19 anos) devem ser orientados a implementar cuidados de prevenção ao câncer de pênis, mas não podem ser atendidos desacompanhados.","para o câncer de pênis, há tratamento paliativo (sem possibilidade de cura), por isso a prevenção é considerada crucial.","no caso de prevenção de câncer de pênis, o autoexame, por se mostrar ineficaz, não integra o conjunto de orientações."],"correta":"A"},{"numero":38,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Na assistência à mulher mãe e a seu bebê, o técnico de enfermagem deve observar com muita atenção o momento da mamada. Uma boa pega facilita a saída do leite e, como consequência, o bebê será alimentado de forma adequada e se evita, também, lesões nos mamilos. Sobre a amamentação, analise as afirmativas a seguir. I. A recomendação é que as mamas estejam c ompletamente expostas e o bebê com os braços livres. II. Os ruídos provenientes da língua do bebê durante a mamada indicam que a técnica está adequada. III. Quando a mama está muito cheia, com a aréola tensa e endurecida, a recomendação é que se retire um pouco de leite, manualmente, antes da mamada. IV. No aconselhamento em amamentação, a linguagem deve ser simples e acessível, e a comunicação não verbal também é um recurso a ser utilizado. Está correto o que se afirma em","alternativas":["III e IV, apenas.","II e III, apenas.","I, II e IV.","I, III e IV.","I, II e III"],"correta":"D"},{"numero":39,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"No dia 27 de julho se comemora o Dia Nacional da Prevenção de Acidentes do Trabalho. A prevenção deve ser perseguida, mas é fato que, no Brasil, ocorrem muitos acidentes relacionados ao trabalho. Sobre esse tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Doenças ocupaci onais podem ser consideradas acidentes de trabalho. ( ) A não aplicação de medidas de segurança coletivas podem ser causas de acidentes de trabalho. ( ) Falta de capacitação, inexperiência, excesso de autoconfiança, trabalho em turnos são algumas das variáveis que contribuem para a ocorrência de acidentes com a equipe de Enfermagem. ( ) De acordo com a NR -6, que trata dos Equipamentos de Proteção Individual (EPI), cabe ao trabalhador responsabilizar- se pela limpeza, guarda e conservação de seu EPI. As afirmativas são, respectivamente,","alternativas":["F – V – F – F.","V – V – F – V.","V – V – V – V.","V – F – F – V.","F – F – F – F"],"correta":"C"},{"numero":40,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"A notificação compulsória é a comunicação obrigatória à autoridade de saúde realizada por meio do Sistema de Informação de Agravos de Notificação (Sinan), que é alimentado, principalmente, pela n otificação e investigação de casos de doenças e agravos que constam da Lista Nacional de Notificação Compulsória de doenças, agravos e eventos em de saúde pública. A respeito da notificação compulsória de casos de doenças e agravos, analise as afirmativas a seguir. I. A portaria GM/MS nº 5.201, de 15 de agosto de 2024 incluiu as seguintes doenças na Lista Nacional de Notificação Compulsória de doenças, agravos e eventos em de saúde pública, nos serviços de saúde públicos e privados em todo o território naci onal: I - Câncer relacionado ao trabalho; II - Dermatose ocupacional; III - Distúrbio de voz relacionado ao trabalho; IV - Infecção pelo vírus da hepatite B em gestante, parturiente ou puérpera e criança exposta ao risco de transmissão vertical da hepatit e B; V - Lesões por Esforços Repetitivos/Distúrbios Osteomusculares Relacionados ao Trabalho (LER/DORT); VI - Perda auditiva relacionada ao trabalho; VII - Pneumoconioses relacionadas ao trabalho; e VIII - Transtornos mentais relacionados ao trabalho. II. A portaria GM/MS nº 5.201, de 15 de agosto de 2024 excluiu as seguintes doenças na Lista Nacional de Notificação Compulsória de doenças, agravos e eventos em de saúde pública, nos serviços de saúde públicos e privados em todo o território nacional: acident e de trabalho com exposição a material biológico, acidente por animal peçonhento e dengue – óbitos, doença de Chagas crônica. III. A notificação compulsória é a comunicação obrigatória à autoridade de saúde, realizada pelos médicos, profissionais de saúde ou responsáveis pelos estabelecimentos de saúde, públicos ou privados, sobre a ocorrência de suspeita ou confirmação de doença, agravo ou evento de saúde pública, podendo ser imediata ou semanal. IV. Para incorporar um agravo ou uma doença à Lista Nacional de Notificação Compulsória de doenças, agravos e eventos em de saúde pública, é necessário considerar alguns aspectos, como características que possam apresentar riscos à saúde pública: potencial para surto ou epidemia; doença ou agravo de causa desconhecida; alteração no padrão clínico-epidemiológico das doenças conhecidas, considerando o potencial de disseminação, a magnitude, a gravidade, a severidade, a transcendência e a vulnerabilidade na população. V. A notificação compulsória é a comunicaçã o obrigatória à autoridade de saúde, que deve ser realizada apenas pelos médicos e enfermeiros, sobre a ocorrência de suspeita ou confirmação de doença, agravo ou evento de saúde pública. Está correto o que se afirma em","alternativas":["I, III e IV, apenas.","I, III e V, apenas.","II, III e V, apenas.","II, III, IV e V.","I, II, III e IV."],"correta":"A"},{"numero":41,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Quando aplicada ao trabalho, a ergonomia tem como objetivo a melhoria das condições de trabalho e da saúde do trabalhador. Em relação ao tema, analise as afirmativas a seguir. I. Na avaliação ergonômica do posto de trabalho, ao sentar -se para digitar os registros de enfermagem no computador, a altura da cadeira deve ser ajustada com relação à mesa, elevando-se ou abaixando -se o assento de forma a permitir que se dobrem os cotovelos em 90. II. O ritmo excessivo de trabalho e a monotonia podem ser considerados riscos ergonômicos. III. Entre outros benefícios, a ginástica laboral (GL) contribui para o fortalecimento muscular. No entanto, uma das consequências da GL é elevar o absenteísmo. IV. De acordo com a NR -17, ao se instituir pausas para propiciar descanso e recuperação psicofisiológica dos trabalhadores, elas devem ser usufruídas fora dos postos de trabalho. Está correto o que se afirma em","alternativas":["I e IV, apenas.","I, II e IV.","II e III, apenas.","I, III e IV.","I e II, apenas"],"correta":"B"},{"numero":42,"disciplina":"Enfermagem","assunto":"Tuberculose","enunciado":"A hanseníase e a tuberculose são doenças crônicas que podem causar complicações graves e sequelas se não tratadas adequadamente. O técnico de enfermagem, como integrante da equipe de saúde, desempenha um papel importante no controle dessas doenças, no acompanhamento contínuo dos pacientes e na prevenção à transmissão. Considerando o atendimento aos pacientes com hanseníase e tuberculose, analise as afirmativas a seguir. I. O tratamento da hanseníase é realizado por meio da associação de medicamentos denominada poliquimioterapia - PQT. II. A hanseníase acomete principalmente os nervos superficiais da pele e troncos nervosos periféricos (localizados na face, no pescoço, no terço médio do braço e abaixo do cotovelo e dos joelhos), mas também pode afetar os olhos e órgãos internos (mucosas, testículos, ossos, baço, fígado etc.). III. Em relação às orientações é importante enfatizar que ambas as doenças têm cura, que o tratamento é gratuito pelo Sistema Único de Saúde, alertando sobre a importância da adesão ao tratamento para evitar a resistência e a falência. IV. A transmissão da tuberculose acontece por via respiratória, pela eliminação de aerossóis pr oduzidos pela tosse, pela fala ou pelo espirro de uma pessoa com tuberculose ativa (pulmonar ou laríngea), sem tratamento. A tuberculose também é transmitida por objetos compartilhados, assim como a hanseníase. V. Para a prevenção de todas as formas de tub erculose e da hanseníase deve -se administrar a vacina BCG (bacilo Calmette-Guérin) em crianças e adultos, disponível nas salas de vacinação das Unidades Básicas de Saúde (UBS) e em algumas maternidades. Está correto o que se afirma em","alternativas":["I, II, III e IV.","I, II e III, apenas.","I, II, III e V.","II, III e IV, apenas.","I, II e V, apenas"],"correta":"B"},{"numero":43,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"As doenças crônicas não transmissíveis (DCNT) estão entre os principais problemas de saúde pública do Brasil e do mundo. Um novo relatório da Organização Pan -Americana da Saúde (OPAS), divulgado em junho de 2024, revela que, embora a expectativa de vida tenha aumentado nas Américas, também aumentou o número de pessoas que vivem com doenças crônicas não transmissíveis, incluindo o Brasil. Sobre as DCNT, assinale a afirmativa correta.","alternativas":["A prevenção das doenças renais crônicas não está diretamente relacionada a estilos e condições de vida das pessoas, pois os fatores de risco preponderantes, como diabetes e hipertensão, são de origem genética.","A causa do tipo de diabetes é apenas genética e a melhor forma de preveni -la é com práticas de vida saudáveis (alimentação, atividades físicas e evitando álcool, tabaco e outras drogas).","A ausência de hábitos saudáveis, juntamente com outros fatores de risco, pode contribuir para o desenvolvimento do diabetes, tais como sobrepeso, principalmente se a gordura estiver concentrada em volta da cintura; doenças renais crônicas; diagnóstico de pré -diabetes; colesterol alto ou alterações na taxa de triglicerídeos no sangue, entre outros.","O monitoramento frequente dos níveis de glicose sanguínea e pressão arterial dos pacientes com diabetes e hipertensão devem ser feitos apenas pelo médico, uma vez que essas condições podem contribuir para o agravam ento da doença renal crônica, que é diagnosticada por este profissional.","A orientação do paciente hipertenso sobre a importância de reduzir a ingestão de sal, realizar exercícios físicos regulares e adotar uma dieta balanceada deve ser feita, apenas, quando aparecer os primeiros sinais de complicação da hipertensão arterial sistêmica"],"correta":"C"},{"numero":44,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"O técnico de enfermagem deve manter -se constantemente atualizado para fornecer o atendimento adequado em situações de urgência e emergência. A s diretrizes da American Heart Association (AHA) para a ressuscitação cardiopulmonar (RCP) e o atendimento cardiovascular de emergência (ACE) são fontes fundamentais de conhecimento para essa atualização. Com base no algoritmo de parada cardiorrespiratória (PCR) para adultos, assinale a afirmativa correta.","alternativas":["Em caso de parada respiratória assistida, a ventilação excessiva deve ser aplicada.","Os responsáveis pela compressão devem alternar a cada dez minutos para que a qualidade da compressão seja mantida.","Os responsáveis pela compressão devem alternar -se a cada cinco minutos para que a qualidade da compressão seja mantida.","Sem via área avançada, a relação entre compressão e ventilação é de 15:2, ou seja, 15 compressões para duas ventilações.","Sem via área avançada, a relação entre compressão e ventilação é de 30:2, ou seja, 30 compressões para duas ventilações."],"correta":"E"},{"numero":45,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente foi admitido na unidade de emergência com sinais e sintomas característicos de choque hipovolêmico, c omo hipotensão, taquicardia, extremidades frias e sudorese. Considerando as medidas iniciais de manejo e as responsabilidades do técnico de enfermagem, assinale a alternativa correta sobre os cuidados a serem realizados, sob supervisão do enfermeiro.","alternativas":["O paciente deve ser mantido em posição supina com os membros inferiores elevados, para facilitar a circulação sanguínea para os órgãos vitais, sem a necessidade de monitoramento contínuo dos sinais vitais.","O monitoramento para as complicações e os efeitos colaterais do tratamento medicamentoso dispensa o relato imediato pelo técnico de enfermagem ao enfermeiro ou ao médico, por se tratar de uma emergência.","O técnico de enfermagem deve solicitar ao médico que suspenda imediatamente o uso de líquidos intravenosos, uma vez que o choque hipovolêmico não exige reposição volêmica.","O técnico de enfermagem deve monitorar continuamente os sinais vitais do paciente, conforme prescrição de enfermagem, como pressão arterial, frequência cardíaca, temperatura e saturação de oxigênio, acompanhando com a equipe a resposta ao tratamento, bem como a evolução do quadro.","O técnico de enfermagem deve monitorar continuamente apenas a pressão arterial para priorizar a resposta ao tratamento, bem como a evolução do quadro"],"correta":"D"},{"numero":46,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Sobre os conceitos de emergência e urgência, e a estrutura e organização do pronto-socorro, assinale a afirmativa correta.","alternativas":["A distinção conceitual entre as condições de urgência e emergência não se trata de um marco regulatório importante e não influencia na classificação de risco nos prontos atendimentos.","Define-se emergência como uma condição de agravo à saúde que implique em risco iminente de vida ou sofrimento intenso, exigindo, portanto, tratamento médico imediato.","A emergência é uma situação médica que pode ser tratada sem pressa, enquanto a urgência requer atendimento imediato, pois há risco iminente de morte ou sequelas.","O pronto-socorro é responsável apenas por atender casos de urgência, não sendo necessário realizar a classificação de risco dos pacientes.","A urgência é um problema de saúde caracterizado como crônico e é no pronto -socorro que estes casos são atendidos, pois é a unidade de saúde responsável pelo atendimento exclusivo de doenças crônicas"],"correta":"B"},{"numero":47,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"A dengue faz parte de um grupo de doenças denominadas arboviroses, que se caracterizam por serem causadas por vírus transmitidos por vetores artrópodes. No Brasil, o vetor da dengue é a fêmea do mosquito Aedes aegypti . A q uase totalidade dos óbitos por dengue é evitável e depende, na maioria das vezes, da qualidade da assistência prestada e organização da rede de serviços de saúde. A equipe de enfermagem desempenha um papel muito importante na prevenção, na promoção e no tratamento de saúde, sendo fundamental o conhecimento da doença para oferecer cuidados adequados e eficazes aos pacientes, além da oferta de educação à comunidade para evitar a proliferação do mosquito transmissor. Sobre a dengue, assinale a afirmativa correta.","alternativas":["Todas as faixas etárias são igualmente suscetíveis à doença, e indivíduos com condições preexistentes, como mulheres grávidas, lactentes, crianças (até dois anos) e pessoas com mais de 65 anos, não apresentam maiores riscos de desenvolver complicações pela doença.","As formas mais comuns de transmissão são por via vertical (de mãe para filho durante a gestação) e por transfusão de sangue.","O tratamento mais indicado é a automedicação com uso de analgésicos e antitérmicos para controle da dor e da febre.","Em períodos fora da sazonalidade da doença, as ações preventivas que devem ser adotadas são uso de telas nas janelas e repelentes em áreas de reconhecida transmissão; remoção de recipientes nos domicílios que possam se transformar em criadour os de mosquitos; vedação dos reservatórios e caixas de água; desobstrução de calhas, lajes e ralos; participação na fiscalização das ações de prevenção e controle da dengue executadas pelo Sistema Único de Saúde.","A urbanização, o crescimento desordenad o da população, o saneamento básico deficitário e os fatores climáticos não afetam a presença do vetor e nem a dinâmica de transmissão desses arbovírus, pois a dengue possui padrão constante, com controle do número de casos e risco para epidemias em todos os meses do ano"],"correta":"D"},{"numero":48,"disciplina":"Enfermagem","assunto":"Hipertensão Arterial","enunciado":"Quanto à aferição da pressão arterial não invasiva, de acordo com as Diretrizes Brasileiras de Hipertensão Arterial (2020), avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Indica-se estimar o nível da pressão arterial sistólica pela palpação do pulso radial. ( ) Deve-se determinar a pressão sistólica no aparecimento dos sons (fase I de Korotkoff). ( ) Deve-se determinar a pressão diastólica no desaparecimento dos sons (fase V de Korotkoff). ( ) É indicado arredondar os valores aferidos para dígitos terminados em zero ou cinco (Ex.: 120/80 mmHg). As afirmativas são, respectivamente,","alternativas":["F – V – F – F.","V – V – F – F.","V – F – V – V.","V – V – V – F.","F – F – F – F."],"correta":"D"},{"numero":49,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"A obesidade é um problema de saúde pública, uma epidemia mundial que acomete grande parte da população adulta e, mais recentemente, adolescentes e crianças. Estima -se que mais de 1,53 bilhão de adultos no mundo estará com excesso de peso em 2035, sendo que hoje, no Brasil, mais de 55% da população adulta apresenta esse problema ( World Obesity Federation , 2024). O profissional de enfermagem deve estar atento a esses índices e aos impactos que isso causa na saúde da população. Considerando o atendimento a pacientes com obesidade, analise as afirmativas a seguir. I. A obesidade é uma condição clínica crônica, resultado da interação de fatores genéticos, metabólicos, ambientais e comportamentais. Está associada a uma série de afecções de saúde, incluindo doenças cardiovasculares, diabetes tipo 2, hipertensão arterial, apneia do sono, certos tipos de câncer, problemas articulares, entre outros. II. A obesidade causa impactos físicos, mas ainda não foi encontrada em pesquisas recentes uma rel ação entre a obesidade e danos psicológicos, como baixa autoestima, ansiedade e depressão. III. A arteriosclerose ou “endurecimento das artérias” é a doença mais comum das artérias. Alguns dos fatores de risco associados à arteriosclerose são obesidade, estresse e falta de atividade física. A enfermagem contribui diretamente para o processo educativo, orientando os pacientes sobre a importância de se engajar em programas de exercícios físicos supervisionados, incentivando a melhoria da alimentação, conforme orientação da equipe de saúde e fornecendo suporte emocional. IV. O tratamento da obesidade envolve apenas a abordagem farmacológica e cirúrgica, sendo a alimentação e o exercício físico complementares a esses tratamentos. Está correto o que se afirma em","alternativas":["I, II, III, IV.","I e II, apenas.","II e III, apenas.","III e IV, apenas.","I e III, apenas"],"correta":"E"},{"numero":50,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Os acidentes com animais peçonhentos são um desafio significativo para a saúde pública no Brasil. Com sua rica biodiversidade e clima tropical favorável, o país abriga uma ampla variedade de serpentes, aranhas, escorpiões e outros animais peçonhentos cujas picadas ou mordidas podem resultar em graves consequências para a saúde das pessoas. Diante desse panorama, é importante que o técnico de enfermagem e a equipe de saúde conheçam e saibam identificar esses animais para garantir um atendimento adequado às vítimas. Sobre o atendimento às vítimas acometidas por estes acidentes, assinale a afirmativa correta.","alternativas":["Animais peçonhentos, como vespas, marimbondos, lacraias, arraias, bagres, entre outros, podem ocasionar acidentes graves. Contudo, esses acidentes não precisam ser notificados no Sistema de Informação de Agravos de Notificação.","Não é necessário encaminhar a o hospital vítimas de picadas por insetos, aracnídeos ou escorpiões, pois a maioria dos casos evolui sem complicações graves. O uso de calor local é o principal cuidado indicado para o alívio da dor de picadas de escorpião.","Compreender que existem dist inções conceituais entre animais peçonhentos e venenosos é fundamental para a correta notificação dos acidentes por animais peçonhentos no Sistema de Informação de Agravos de Notificação do Ministério da Saúde.","O uso de torniquete nas extremidades afetadas é altamente recomendado em todos os casos de picadas de serpentes para evitar a circulação do veneno.","Para o tratamento das manifestações tóxicas ocasionadas por uma ou poucas picadas de abelhas, a principal medida imediata é a aplicação de calor local para neutralizar o veneno"],"correta":"C"},{"numero":51,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"Os produtos para a saúde utilizados em procedimentos diagnósticos e terapêuticos são classificados de acordo com o risco de transmissão de infecção. Com base na RDC nº 15/2012 da Anvisa, avalie as afirmativas a seguir que tratam dos tipos de produtos processáveis para saúde. I. Os produtos para saúde semicríticos devem ser submetidos à limpeza e desinfecção de alto nível. II. Os produtos para saúde semicríticos são aqueles que entram em contato com mucosas ou pele não íntegra. III. Os produtos para saúde críticos devem ser obrigatoriamente limpos e esterilizados. IV. Os produtos para saúde não críticos são aqueles que entram em contato com a pele íntegra e devem ser limpos e esterilizados. Estão corretas as afirmativas","alternativas":["I, II e III, apenas.","II e IV, apenas.","I e II, apenas.","III e IV, apenas.","I, II, III e IV."],"correta":"A"},{"numero":52,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"Leia as situações a seguir e analise a adequação dos métodos de desinfecção empregados. Nessa análise, considere os conceitos de desinfecção de alto nível e de nível intermediário, conforme definidos na RDC nº 15/2012 da Anvisa, que regulamenta o processamento de produtos para a saúde. I. Um endoscópio flexível foi submetido à limpeza manual, seguida de desinfecção química com um agente que destrói microbactérias e esporos bacterianos. II. Uma cama hospitalar foi desinfetada com solução à base de hipoclorito de sódio 0,5%. III. Um nebulizador utilizado foi desinfetado com álcool etílico 70%. IV. Um termômetro digital foi desinfetado com álcool etílico 70%. Estão corretas, de acordo com a RDC nº 15/2012 da ANVISA, as situações","alternativas":["I, II e III, apenas.","I, II e IV, apenas.","II e III, apenas.","I, II, III e IV.","I, III e IV, apenas"],"correta":"B"},{"numero":53,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"Sobre os requisitos para o processamento de produtos para saúde, de acordo com a RDC nº 15/2012 da Anvisa, analise as afirmativas a seguir. I. Não é permitido o uso de embalagens de papel kraft, assim como de envelopes de plástico transpar ente, que não sejam especificamente destinados ao uso em equipamentos de esterilização. II. Não é permitido o uso de caixas metálicas sem furos para esterilização de produtos para saúde. III. O papel grau cirúrgico não é compatível com esterilização a vapor. IV. As embalagens utilizadas para esterilização devem estar regularizadas junto à Anvisa para o uso específico. Está correto o que se afirma em","alternativas":["I, II e III.","I e III, apenas.","I, II e IV.","II, III e IV.","III e IV, apenas"],"correta":"C"},{"numero":54,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"A temperatura corporal é a diferença entre a quantidade de calor produzido por processos do corpo (metabolismo) e a quantidade de calor perdido para o ambiente externo, podendo variar entre 36 oC e 38 oC, a depender do local de mensuração. Acerca do tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A temperatura oral é geralmente 0,5 oC maior que a axilar. ( ) A temperatura axilar é geralmente 0,5 oC menor que a retal. ( ) A temperatura oral é geralmente 1,0 oC menor que a retal. As afirmativas são, respectivamente,","alternativas":["F – V – V.","F – V – F.","V – F – V.","V – V – V.","V – V – F"],"correta":"E"},{"numero":55,"disciplina":"Enfermagem","assunto":"Tuberculose","enunciado":"Um paciente foi diagnosticado com tuberculose pulmonar ativa e está internado em um hospital. A conduta do técnico de enfermagem que reflete corretamente o controle de infecção na situação citada é","alternativas":["usar máscara N95 ou equivalente, avental descartável e luvas, realizando a higienização das mãos antes e após o contato com o paciente.","usar apenas luvas descartáveis durante o atendimento, uma vez que o contato direto com secreções é mínimo.","higienizar as mãos antes e após o contato com o paciente, utilizando máscara cirúrgica comum e luvas para proteger -se de partículas respiratórias.","manter o paciente em quarto coletivo com outros pacientes que tenham diagnósticos similares, utilizando apenas avental descartável durante o atendimento.","colocar o paciente em precaução de contato apenas se ele apresentar secreções visíveis, não sendo necessário o uso de máscara pelo técnico de enfermagem"],"correta":"A"},{"numero":56,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Sobre a atuação do técnico de enfermagem nos principais tipos de acidentes, assinale a afirmativa correta.","alternativas":["No plano de cuidados de enfermagem a pacientes acometidos por queimaduras, é importante planejar os procedimentos de forma a minimizar o tempo de exposição das feridas, quando necessário, a fim de reduzir a perda de calor pela lesão.","O atendimento ao politrauma envolve, primeiramente, a hiperextensão e/ou a lateralização da cabeça.","Em situações de afogamento, não se deve manipular a vítima e deve -se mantê -la com as roupas molhadas, sem aquecimento, mesmo na ausência de trauma.","Na intoxicação por drogas de abuso, deve -se estimular o vômito da vítima inconsciente.","A higienização das mãos antes e depois de cada contato com pacientes acometidos por queimaduras é dispensável, pois, como esses pacientes já estão infectados, não há risco de transmissão de novas infecções"],"correta":"A"},{"numero":57,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Durante a administração de oxigenoterapia em um paciente com DPOC (Doença Pulmonar Obstrutiva Crônica), o técnico de enfermagem deve estar atento a diversos fatores para garantir a eficácia do tratamento e evitar complicações. Para garant ir uma prática segura e adequada nesse tipo de cuidado, o técnico de enfermagem deve","alternativas":["ajustar o fluxo de oxigênio a 10 L/min para todos os pacientes, independentemente da prescrição médica, para garantir a oxigenação adequada.","monitorar sinais de hipoventilação em pacientes com DPOC e utilizar baixo fluxo de oxigênio, conforme prescrição médica.","substituir a máscara de Venturi por uma máscara simples para aumentar a concentração de oxigênio quando necessário.","interromper imediatamente a oxige noterapia se o paciente relatar sensação de desconforto ao usar a máscara.","utilizar oxigenoterapia contínua em pacientes com saturação acima de 95%, mesmo na ausência de prescrição, para prevenir hipóxia."],"correta":"B"},{"numero":58,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Um técnico de enfermagem es tá administrando uma medicação intravenosa em bolus e precisa garantir a segurança do procedimento. Nessa situação, avalie se o técnico de enfermagem deve I. verificar a compatibilidade do medicamento com o fluido intravenoso já em uso antes da administração. II. monitorar sinais de reações adversas durante e após a administração do medicamento. III. confirmar a identidade do paciente utilizando pelo menos dois identificadores antes de iniciar a administração. IV. realizar o flush da via intravenosa com so lução salina antes e após a administração para evitar obstruções. Estão corretas as afirmativas","alternativas":["I, II e III, apenas.","II e III, apenas.","I, II, III e IV.","I, III e IV, apenas.","II, III e IV, apenas"],"correta":"C"},{"numero":60,"disciplina":"Enfermagem","assunto":"Centro Cirúrgico","enunciado":"A atuação do técnico de enfermagem nos períodos pré-operatório, transoperatório e pós-operatório é essencial para a segurança do paciente e o sucesso do procedimento cirúrgico. Assinale a afirmativa que representa uma prática a ser aplicada na situação descrita.","alternativas":["No pré -operatório, realizar a tricotomia no centro cirúrgico imediatamente antes da indução anestésica, utilizando lâmina de barbear.","No transoperatório, garantir que as contagens de compressas e instrumentos sejam realizadas exclusivamente pelo enfermeiro circulante, sem necessidade de acompanhamento do técnico de enfermagem.","No pós -operatório imediato, priorizar a aplicação de cobertores térmicos para prevenir hipotermia, mesmo antes de avaliar os sinais vitais do paciente.","No pré-operatório, dispensar a confirmação da lateralidade ou do local cirúrgico, considerando que isso já é verificado pelo cirurgião antes do procedimento.","No pós -operatório, auxiliar na mobilização precoce do paciente, sempre respeitando as orientações específicas da equipe médica e da de enfermagem."],"correta":"E"}]},{"id":"ebserh2025-tecnico-trabalho","cargo":"Técnico em Enfermagem — Saúde do Trabalhador, Grupo 16, Tipo 1","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/grupo-16-tecnico-em-enfermagem-especializacao-tecnica-em-saude-do-trabalhadore3cnmgp16-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ebserrhassistencial2024_gabarito_definitivo.pdf","itens":[{"numero":31,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Ao preparar a administração de medicamento endovenoso no posto de enfermagem, uma das apresentações de medicamentos é em forma de frasco-ampola. Ao final da aspiração, o frasco será descartado. De acordo com a RDC nº 222, de 28 de março de 2018, sobre o descarte desse tipo de frasco de medicamentos, é correto afirmar que","alternativas":["no caso de descartá-lo em recipientes de papelão em bancadas com pia, recomenda -se que estes r ecipientes fiquem suspensos por suporte para evitar o contato com água.","não podem ser descartados em recipiente de papelão, pois trata-se de resíduo classificado como produto químico.","o frasco -ampola não é considerado “resíduo de serviços de saúde” e, portanto, a RDC nº 222 de 2018 não se aplica ao seu descarte.","obrigatoriamente, o descarte de frascos -ampola de medicamentos deve ser feito em saco branco leitoso.","se o frasco -ampola for de antibiótico, o descarte só pode ser feito em sacos vermelhos"],"correta":"A"},{"numero":32,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"Profissionais de saúde lidam com a vida e são postos diariamente frente a dilemas, muitos deles de cunho ético. Para uma atuação segura, o profissional deve se valer dos princípios universais da bioética e dos dispositivos legai s da profissão. Por isso o profissional precisa conhecer a legislação e saber aplicá -la na orientação de suas ações, na garantia dos direitos humanos, dos direitos e deveres profissionais. Sobre esse tema, avalie as afirmativas a seguir. I. O Código de Ética dos Profissionais de Enfermagem menciona a Declaração Universal sobre Bioética e Direitos Humanos de 2005; no âmbito dessa Declaração, o s interesses e o bem-estar do indivíduo devem ter prioridade sobre o interesse exclusivo da ciência ou da sociedade. II. Um trabalhador pede demissão por estar insatisfeito com a instituição e passa a difamá-la e também ao Conselho Regional de Enfermagem de seu estado; de acordo com o Código de Ética dos Profissionais de Enfermagem , essa infração é considerada grave e passível de receber como penalidade a censura. III. Para dar segurança aos usuários, uma instituição de saúde propôs a um trabalhador técnico de enfermagem a filmagem de atividades realizadas por ele, utilizando corretamente os equipamentos de proteção individual, com o objetivo de compor conteúdos das mídias sociais da instituição; pautado no Código de Ética dos Profissionais de Enfermagem, o técnico de enfermagem pode se negar a atender a esse pedido. Está correto o que se afirma em","alternativas":["I e II, apenas.","II e III, apenas.","I, II e III.","III, apenas.","I e III, apenas."],"correta":"E"},{"numero":33,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A vigilância em saúde ambiental se dedica ao estudo e à proposição de medidas de atenção integral à saúde de pessoas expostas a riscos relacionados a substâncias químicas advindas das inter-relações entre o homem e o ambiente. No atendimento de enfermagem a um adulto trabalhador com intoxicação aguda por agrotóxicos, assinale a afirmativa correta.","alternativas":["Na medida dos sinais vitais, a FC (fr equência cardíaca) foi de menos de 40; nesse caso, essa taquicardia indica comprometimento cardiovascular.","Se o trabalhador em questão estiver com sintomas leves, o técnico de enfermagem atua no monitoramento por um período mínimo de 6 a 12 horas, acom panhando os seguintes parâmetros: estado de alerta; sinais neurológicos; sinais vitais; se possível, oximetria de pulso.","Nas estratégias terapêuticas indicadas não se considera a toxicodinâmica da substância química, mas apenas a sua toxicocinética, pois, para o tratamento, é importante saber a distribuição, o metabolismo e a excreção do agente tóxico.","Na realização do cuidado de descontaminação ocular, os olhos devem ser lavados com as pálpebras abertas e com fluxo contínuo de água, pois no caso de intoxicação com agrotóxico não se pode usar solução fisiológica.","No caso de descontaminação gástrica, o técnico de enfermagem deve ajudar o paciente na indução ao vômito e usar Equipamento de Proteção Individual (EPI)"],"correta":"B"},{"numero":34,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A Por taria GM/MS nº 502, de 1º de junho de 2023, institui o Programa Nacional de Controle do Tabagismo (PNCT) no âmbito do Sistema Único de Saúde (SUS). Considerando os eixos estruturantes desse Programa, o técnico de enfermagem exerce um importante papel junto aos trabalhadores, de modo a ajudá -los nas medidas de promoção da saúde, prevenção e tratamento do tabagismo. Para uma atuação responsável e eficaz, o conhecimento sobre esse tema é primordial na elaboração de ações de educação em saúde. Nesse contexto, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O fumo passivo acomete especialmente as crianças, que correm o risco de desenvolver pneumonia, bronquite, agravamento de asma; com os adultos ocorrem incômodos, mas eles não correm risco de ter as mesmas doenças que o fumante. ( ) Deve-se informar ao tabagista que, entre os tratamentos disponíveis no SUS, há o medicamentoso por meio de adesivo, goma e pastilha, e que a duração do tratamento é de 12 meses e inclui a manutenção da abstinência. ( ) Se o trabalhador manifestar preocupação com o ganho de peso deve ser orientado para o fato de que isso é temporário, e que, na maioria dos casos, ocorre nos primeiros meses pós-cessação. ( ) A alternativa de uso de cigarro s eletrônicos deve ser descartada, pois ele aumenta o risco para a síndrome respiratória aguda grave e, além disso, os cigarros eletrônicos podem causar danos ambientais tais como incêndios e explosões. As afirmativas são, respectivamente,","alternativas":["F – V – V – F.","V – F – V – F.","F – V – V – V.","V – V – F – V.","F – V – F – V"],"correta":"C"},{"numero":35,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Na análise dos ambientes de trabalho é fundamental aplicar os conhecimentos de ergonomia. E observar a postura na realização do trabalho é importante para respeitar a biomecânica. Sobre a relação da ergonomia e a biomecânica, assinale a afirmativa correta.","alternativas":["Ao usar o computador ( desktop), o trabalhador deve posicionar o monitor na sua frente e regular a altura da tela para ficar com uma distância entre 30 e 50 cm, para que tenha mais conforto visual.","Quem trabalha escrevendo por muito tempo, deve ser orientado a manter a mão, o punho e até a metade do antebraço apoiados na mesa, para manter uma posição de conforto.","Uma das posições usadas por mecânicos de automóveis é a posição deitada. Esta posição costuma ser confortável e não causa esforço estático no tronco e cabeça no tipo de trabalho realizado por estes trabalhadores.","O trabalhador que precisar se manter na posição ortostát ica por muito tempo, deve alternar o peso do corpo de um pé para o outro para descansar os músculos das coxas e pernas.","No desenvolvimento do trabalho na posição de pé, ocorre acentuação da cifose e da escoliose e, por isso, quadril e ombros devem se alinhar de forma assimétrica"],"correta":"D"},{"numero":36,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Os rompimentos de barragens ocorridos neste século, em Minas Gerais, despejaram milhões de metros cúbicos de rejeitos de minério de ferro e sílica no meio ambiente, além de outros metais pesados. Essas trag édias ambientais evidenciaram ainda mais a importância da vigilância em saúde ambiental, saúde pública e as relações entre a saúde ambiental e a saúde do trabalhador. Em relação ao tema, avalie as afirmativas a seguir. I. Um dos componentes da vigilância e m saúde ambiental é a Vigipeq, que trata da Vigilância em Saúde de Populações Expostas a Substâncias Químicas. II. A vigilância à exposição ambiental aos metais pesados na população exposta às citadas tragédias ambientais deve ser feita para monitorar as c onsequências, especialmente no que se refere ao controle e prevenção do câncer. III. O biomonitoramento humano de substâncias químicas (BioH) é um método de avaliação da exposição humana às substâncias químicas e seus efeitos; por meio da Portaria GM/MS nº 2.018, de 27 de novembro de 2023, o Ministério da Saúde instituiu um grupo de trabalho para elaborar proposta de programa de biomonitoramento humano de substâncias químicas do Brasil. Está correto o que se afirma em","alternativas":["I, II e III.","II, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas."],"correta":"A"},{"numero":37,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Uma das provas funcionais na atenção à saúde do trabalhador e da aptidão para o exercício do trabalho é a avaliação da força muscular por meio do exame de dinamometria. Sobre a força muscular e o exame de dinamometria, avalie as afirmativas a seguir. I. A dinamometria escapular é específica para avaliar a força de preensão das mãos. II. A temperatura ambiente é um dos fatores que influenciam na força muscular. III. No exame de avaliação da resistência estática de membros superiores, o técnico de enfermagem deve oferecer ao trabalhador halteres apropriados para a realização do exame. Está correto o que se afirma em","alternativas":["I e II, apenas.","II e III, apenas.","I e III, apenas.","I, II e III.","II, apenas"],"correta":"B"},{"numero":38,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Um dos problemas que acomete os trabalhadores decorre de utilização excessiva (sobrecarga) de determinados grupamentos osteomusculares. Para cuidar da saúde do trabalhador nos casos de Lesão por Esforço Repetitivo (LER) e Distúrbios Osteomusculares Relacionados ao Trabalho (DORT), há cuidados relacionados tanto à prevenção quanto ao tratamento. Sobre a prevenção e o tratamento de LER e DORT, é correto afirmar que","alternativas":["no caso de diagnósti co de LER/DORT, faz -se tratamento sintomático e acolhimento ao trabalhador, mas não há medidas que possibilitem seu retorno ao trabalho na mesma função/atividade.","em um programa de prevenção de LER/DORT devem -se considerar os fatores de risco, que são apenas biomecânicos, sensoriais e de organização do trabalho.","conhecer os seguintes aspectos, entre outros, da organização do trabalho é importante nos programas de prevenção: ausência de pausas, organização da produção, exigência de habilidades sincro nizada com esforço físico e relações interpessoais.","projetos mobiliários devem fazer parte dos programas de prevenção para atender às características antropométricas dos trabalhadores; a NR -17 trata das questões antropométricas, mas não aborda o tópico relativo aos mobiliários dos postos de trabalho.","ginástica laboral é uma estratégia aplicada em algumas instituições para viabilizar a prática de exercícios físicos durante a jornada de trabalho; há três tipos de ginástica laboral, mas nenhuma delas é indicada como prevenção de LER/DORT"],"correta":"C"},{"numero":39,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Doenças infectocontagiosas são sempre preocupantes e podem comprometer de forma importante a saúde do trabalhador. Nesse sentido, o técnico de enfermagem precisa conhecer os meios de propagação e as precauções a serem aplicadas no atendimento de trabalhadores quando se tratar deste tipo de doenças. Nesse contexto, avalie as afirmativas a seguir. I. Na medição da temperatura de um trabalhador com varicela, deve-se tomar cuidado apenas c om o contato direto com as vesículas, a única via de transmissão. II. Um trabalhador diagnosticado com caxumba que precisa ser transportado para um atendimento hospitalar, deve seguir com máscara cirúrgica. III. Nos casos de sarampo, para reduzir os riscos de propagação da doença, tanto para casos suspeitos como para os confirmados, a pessoa deve evitar a ida ao trabalho por pelo menos quatro dias, a partir da data de aparecimento do exantema. Está correto o que se afirma em","alternativas":["I e III, apenas.","I e II, apenas.","I, II e III.","II, apenas.","II e III, apenas"],"correta":"E"},{"numero":40,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"O exercício do trabalho deve ser feito em condições de segurança e qualidade ambiental que previna a ocorrência de desconfortos, doenças e acidentes ocupacionais. Sobre a exposição a ruídos no ambiente laboral, é correto afirmar que","alternativas":["as leituras dos níveis de ruídos de impacto devem ser feitas a uma distância mínima de 50 cm do ouvido do trabalhador.","as leituras dos níveis de tolerância para ruídos de impacto são feitas pela unidade de frequência do som (em hertz).","a classificação se o ruído é ou não de impacto tem caráter subjetivo e é feita pelo próprio trabalhador.","a máxima exposição diária permissível em oito horas para ruídos contínuos ou intermitentes é de 85 decibéis (dB).","o tempo de exposição aos níveis de ruído não deve exceder aos limites de tolerância fixados pelas Comissões Internas de Prevenção de Acidentes e Assédio (CIPA), que varia em cada empresa/instituição."],"correta":"D"},{"numero":41,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A Norma Regulamentadora nº 4 (NR -4), caracterizada como Norma Geral pela Portaria SIT nº 787, de 28 de novembro de 2018, estabelece requisitos para os Serviços Especializados em Engenharia de Segurança e em Medicina do Trabalho (SESMT) nas empresas. De acordo com essa norma, a quantidade de profissionais do SESMT a ser contratada depende de alguns fatores. Com base na NR -4, assinale a afirmativa correta a respeito do tema.","alternativas":["O SESMT deve ser composto por médicos do trabalho, engenheiros de segurança, enfermeiros do trabalho e técnicos de segurança, de forma obrigatória, em todas as empresas de qualquer porte.","O SESMT é uma obrigação apenas para empresas de grande porte, independentemente do grau de risco da atividade.","A NR -4 estabelece que o SESMT deve ser composto por médicos do trabalho, dispensando outros profissionais, como engenheiros de segurança e enfermeiros.","A quantidade e a composição do SESMT dependem do número de empregados da empresa e da natureza do risco da atividade econômica da empresa.","As empresas de grande porte não precisam contratar profissionais do SESMT, se realizarem treinamentos de segurança e saúde do trabalhador por meio de consultorias externas"],"correta":"D"},{"numero":42,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Conforme classificação estabelecida na Portaria SIT n° 787, de 29 de novembro de 2018, a Norma Regulamentadora nº 6 é norma especial, posto que regulamenta a execução do trabalho com uso de Equipamentos de Proteçã o Individual (EPI), sem estar condicionada a setores ou atividades econômicas específicas. Em relação ao Equipamento de Proteção Individual (EPI), cabe à organização","alternativas":["solicitar a colaboração do empregado em relação ao seu uso, enfatizando que a utilização é facultativa.","adquirir os EPIs e fornecê -los aos empregados, não sendo necessário treinamento ou orientação sobre o seu uso.","registrar o seu fornecimento ao empregado, podendo ser adotados livros, fichas ou sistema eletrônico, inclusive, por sistema biométrico para esse fim.","fornecer EPIs adequados ao risco, mas não é sua responsabilidade garantir a manutenção ou substituição dos equipamentos danificados ou extraviados.","exigir o uso de EPIs periodicamente, ou seja, quando houver fiscalização por parte de órgãos competentes em segurança e saúde no trabalho"],"correta":"C"},{"numero":43,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Na atuação profissional, para o exercício pleno de suas funções, o técnico de enfermagem do trabalho precisa ter conhecimento da Consolidação das Leis do Trabalho (C LT), que estabelece diversas obrigações do empregador para garantir a segurança e saúde dos trabalhadores no ambiente de trabalho. Com base na CLT, acerca d as atividades insalubres ou perigosas, avalie as afirmativas a seguir. I. Serão consideradas ativida des ou operações insalubres aquelas que, por sua natureza, condições ou métodos de trabalho, exponham os empregados a agentes nocivos à saúde acima dos limites de tolerância fixados em razão da natureza e da intensidade do agente e do tempo de exposição ao s seus efeitos. II. A eliminação ou a neutralização da insalubridade ocorrerá com a utilização de equipamentos de proteção individual ao trabalhador, que diminuam a intensidade do agente agressivo a limites de tolerância. III. A eliminação ou a neutralização da insalubridade ocorrerá com a adoção de medidas que conservem o ambiente de trabalho sem limites de tolerância e com a utilização de equipamentos de proteção individual ao trabalhador. IV. O exercício de trabalho em condições insalubres, ac ima dos limites de tolerância estabelecidos pelo Ministério do Trabalho, assegura a percepção de adicional de até 20% do salário-mínimo da região ao trabalhador, independentemente de classificação dos graus de risco. As afirmativas corretas são","alternativas":["I, II, III e IV.","II, III e IV, apenas.","I, III e IV, apenas.","I e II, apenas.","II e III, apenas"],"correta":"D"},{"numero":44,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A Norma Regulamentadora nº 9, NR -9, estabelece os requisitos para a avaliação das exposições ocupacionais a agentes físicos, químicos e biológicos quando identificados no Programa de Gerenciamento de Riscos - PGR, previsto na NR-1, e subsidia o PGR quanto às medidas de prevenção para os riscos ocupacionais. Com base nessa norma sobre exposição ocupacional às Vibrações em Mãos e Braç os (VMB) e às Vibrações de Corpo Inteiro (VCI), é correto afirmar que","alternativas":["no processo de eliminação ou redução dos riscos relacionados à exposição às vibrações mecânicas devem ser considerados, entre outros fatores, os esforços físicos, e descartados os aspectos posturais.","é facultativo à organização comprovar, no âmbito das ações de manutenção preventiva e corretiva de veículos, máquinas, equipamentos e ferramentas, a adoção de medidas que visem ao controle e à redução da exposição a vibrações.","as organizações devem adotar medidas de prevenção e controle da exposição às vibrações mecânicas que possam afetar a segurança e a saúde dos trabalhadores, eliminando o risco ou, onde comprovadamente não houver tecnologia disponível, reduzindo-o aos menores níveis possíveis.","as organizações devem adotar medidas de prevenção e controle da exposição às vibrações mecânicas em casos em que o trabalhador já apresente sinais de danos à saúde.","a redução da exposição às vibrações mecânicas é facultativa em ambientes onde não haja regulamentação específica, uma vez que a saúde dos trabalhadores nem sempre é diretamente afetada por esse risco."],"correta":"C"},{"numero":45,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"No 10º Encontro Nacional das Comissões Intersetoriais de Saúde do Trabalhador e da Trabalhadora (Cist tão), realizado pelo Conselho Nacional de Saúde (CNS) em parceria com a Secretaria de Vigilância em Saúde e Ambiente (SVSA/MS), em julho de 2024, destacou-se que a saúde do trabalhador e da trabalhadora deve ser observada e discutida para além dos espectro s dos direitos trabalhista, previdenciário e sanitário, e finalmente alcançar o patamar dos direitos humanos. Essa reflexão, discutida até os dias atuais, remonta ao movimento sanitarista, e culminou com seu reconhecimento na Constituição Federal de 1988. No que se refere ao contexto da saúde do trabalhador e competência do Sistema Único de Saúde no Art. 200 da Constituição Federal de 1988, assinale a afirmativa correta.","alternativas":["A saúde do trabalhador é atualmente uma responsabilidade da Previdência Social, qu e deve fornecer os cuidados médicos necessários quando o trabalhador adquire doenças ocupacionais, sem envolver a atuação de outros órgãos ou políticas públicas de saúde.","A Constituição Federal de 1988, em seu Art. 200, assegura a execução de ações de vigilância sanitária, epidemiológica e de saúde do trabalhador e colaboração na proteção do meio ambiente, nele compreendido o do trabalho.","A Constituição Federal de 1988 assegura que a saúde do trabalhador é um direito de trabalhadores formais com carteira assinada, não se aplicando a trabalhadores informais ou autônomos.","A saúde do trabalhador é uma questão trabalhista, sendo de competência única do Ministério do Trabalho e Emprego, e não se relaciona com os direitos humanos ou com a saúde pública, conforme preconizado pela Constituição Federal.","A Constituição Federal de 1988 assegura cuidados médicos do trabalhador em relação às condições de aquisição de doença no trabalho, sem se estender à promoção da saúde em um sentido mais amplo, como direito humano"],"correta":"B"},{"numero":46,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"De acordo com a NR -9, que estabelece os parâmetros para a elaboração e implementação do Programa de Prevenção de Riscos Ambientais (PPRA), assinale a opção que descreve corretamente os elementos que devem fazer parte da estrutura mínima do PPRA.","alternativas":["O PPRA deve conter planejamento anual, estratégias de ação, registros e forma de avaliação do desenvolvimento, sendo dispensável estabelecer um cronograma.","O PPRA deve estabelecer metas e cronograma sem necessidade de estabelecer estratégias ou avaliação contínua.","O PPRA deve conter a definição de metas e o cronograma de ações, sem necessidade de outras informações adicionais.","O PPRA deve ser realizado uma única vez, sem necessidade de atualização ou avaliação de suas ações ao longo do ano.","O PPRA deve conter planejamento anual, estratégias e metodologia de ação, forma de registro e manutenção dos dados, e a periodicidade e forma de avaliação do desenvolvimento"],"correta":"E"},{"numero":47,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A Organização Internacional do Trabalho (OIT) foi fundada em 1919 com o objetivo de promover a justiça social e melhorar as condições de trabalho em todo o mundo. A OIT tem como um de seus principais objetivos promover normas internacionais para a proteção dos direitos dos trabalhadores, através de Convenções. Por ocasião da reunião do G20, sediada na cidade do Rio de Janeiro em 2024, a OIT pediu ao G20 para reduzir as desigualdades, promover a igualdade de gênero e incentivar a diversidade no mundo do trabalho. Sobre as Convenções da OIT, avalie as afirmativas a seguir. I. As convenções são tratados internacionais sobre um tema determinado, que estabelecem princípios e diretrizes a serem observados pelos países que as assinam. II. As Convenções da OIT são limitadas a condições de trabalho exclusivamente para trabalhadores formais com carteira assinada, não abrangendo trabalhadores informais ou autônomos. III. Indenização por doenças profissionais (Convenção 42), trabalho noturno de mulheres na indústria (Co nvenção 89), proteção ao salário (Convenção 95), igualdade salarial entre homens e mulheres (Convenção 100), amparo à maternidade (Convenção 103), discriminação em matéria de emprego e profissão (Convenção 111), férias (Convenção 132), incentivo à negociaç ão coletiva (Convenção 154) e piores formas de trabalho infantil e ação imediata para sua eliminação (Convenção 182) são algumas das Convenções ratificadas pelo Brasil. IV. A OIT não possui influência sobre as questões de segurança e saúde no trabalho, sen do sua atuação restrita a questões trabalhistas relacionadas a salários e jornada de trabalho. Estão corretas as afirmativas","alternativas":["I e III, apenas.","I, II e III, apenas.","I, II, III e IV.","III e IV, apenas.","II e IV, apenas"],"correta":"A"},{"numero":48,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"As Normas de Higiene Ocupacional (NHOs) compõem uma série de normas técnicas resultantes dos trabalhos técnicos da Fundacentro. Elas abordam diferentes aspectos dos procedimentos e critérios de identificação, avaliação e controle dos riscos e perigos ambientais e profissionais. As NHOs têm como objetivo principal","alternativas":["fomentar a adoção de medidas preventivas contra doenças profissionais e quaisquer outros riscos e fatores potencialmente danosos à saúde e à segurança dos trabalhadores em diversos ambientes ocupacionais.","fornecer subsídios para a eliminação de todos os riscos ocupacionais sem a necessidade de medidas preventivas.","criar ambientes livres de riscos físicos, desconsiderando agentes químicos e biológicos.","regulamentar salários e condições de trabalho, sem abordar os riscos ambientais.","estimular a formação acadêmica de profissionais da área de saúde, sem relação direta com a segurança no trabalho."],"correta":"A"},{"numero":49,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A prevenção de acidentes é o conjunto de práticas e medidas para identificar e mitigar riscos no ambiente de trabalho, promovendo segurança para os trabalhadores e trabalhadoras. A NR -05 estabelece os parâmetros e os requisitos da Comissão Interna de Prevenção de Acidentes e de Assédio (CIPA) tendo por objetivo a prevenção de acidentes e doenças relacionadas ao trabalho, de modo a tornar compatível permanentemente o trabalho com a preservação da vida e promoção da saúde do trabalhador. Sobre a CIPA, assinale a afirmativa correta.","alternativas":["O acompanhamento do processo de identificação de perigos e avaliação de riscos bem como a adoção de medidas de prevenção implementadas pela organização e pela CIPA são facultativos.","A CIPA tem como objetivo a prevenção de acidentes e doenças decorrentes do trabalho, de modo a tornar compatível, de forma permanente, o trabalho com a preservação da vida e a promoção da saúde do trabalhador.","A verificação de ambientes e das condições de trabalho visando identificar situações que possam trazer riscos para a segurança e saúde dos trabalhadores pela CIPA é recomendada exclusivamente para empresas de médio e grande porte.","Cabe à CIPA solicitar à organização informações relacionadas à segurança e saúde dos trabalhadores, salvo as Comunicações de Acidente de Trabalho (CAT), as quais exigem sigilo médico e proteção das informações pessoais dos envolvidos.","A CIPA deve ser constituída por estabelecimento, composta por representantes do empregador e dos empregados, e dimensionada de acordo com o número de ambientes da empresa"],"correta":"B"},{"numero":50,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Para a administração de dipirona por via intramuscular (IM), é fundamental seguir as normas técnicas e os protocolos de segurança para garantir a eficácia do medicamento e a prevenção de complicações, como lesões teciduais ou infecções. Considerando as boas práticas de enfermagem, assinale a opção que descreve corretamente a técnica para essa administração.","alternativas":["Higienizar as mãos, preparar o medicamento, posicionar o paciente em decúbito lateral, escolher o músculo ventroglúteo, introduzir a agulha em ângulo de 90 , aspirar antes de aplicar e descartar a agulha em recipiente adequado.","Higienizar as mãos, preparar o medicamento, posicionar o paciente sentado, escolher o músculo glúteo, introduzi r a agulha em ângulo de 45  e aplicar sem necessidade de aspiração.","Higienizar as mãos, preparar o medicamento, posicionar o paciente em decúbito ventral, escolher o músculo vasto lateral da coxa, introduzir a agulha em ângulo de 90, aspirar antes de aplicar e realizar movimentos circulares ao retirar a agulha.","Higienizar as mãos, preparar o medicamento na seringa, posicionar o paciente em decúbito dorsal, escolher o músculo deltoide, introduzir a agulha em ângulo de 90  e realizar movimentos circulares ao retirar a agulha.","Higienizar as mãos, preparar o medicamento, posicionar o paciente sentado, escolher o músculo deltoide, introduzir a agulha em ângulo de 45, aplicar o medicamento e massagear vigorosamente após a retirada da agulha"],"correta":"A"},{"numero":51,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"A Política Nacional de Segurança e Saúde no Trabalho -PNSST tem por objetivos a promoção da saúde e a melhoria da qualidade de vida do trabalhador e a prevenção de acidentes e de danos à saúde advindos, relacionados ao trabalho ou que ocorram no curso dele, por meio da eliminação ou redução dos riscos nos ambientes de trabalho. Com base na Política Nacional de Segurança e Saúde no Trabalho, assinale a afirmativa correta.","alternativas":["Para o alcance de seu objetivo, a Política Nacional de Segurança e Saúde no Trabalho deverá ser implementada por meio da articulação continuada das ações das empresas no campo das relações de trabalho, produção, consumo, ambiente e saúde, com a participação obrigatória das organizações representativas de trabalhadores e empregadores.","As ações desenvolvidas no âmbito da Política Nacional de Segurança e Saúde no Trabalho devem constar do Plano Nacional de Segurança e Saúde no Trabalho e incluir todos os trabalhadores brasileiros com carteira assinada no Sistema Nacional de Promoção e Proteção da Saúde.","Cabe aos Ministérios do Trabalho e Emprego a implementação e a execução da Política Nacional de Segurança e Saúde no Trabalho.","Cabe à Organização Internacional do Trabalho (OIT), nos assuntos de sua área de competência, acompanhar o cumprimento, em âmbito nacional, dos acordos e convenções ratificados pelo Governo brasileiro junto aos organismos internacionais.","A Política Nacional de Segurança e Saúde no Trabalho tem por princípios: a universalidade; a prevenção; a p recedência das ações de promoção, proteção e prevenção sobre as de assistência, reabilitação e reparação; o diálogo social; a integralidade"],"correta":"E"},{"numero":52,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Os transtornos mentais relacionados ao trabalho são condições que podem surgir a partir de fato res psicossociais e organizacionais no ambiente laboral. Sobre a vigilância e a notificação desses agravos, é correto afirmar que","alternativas":["os transtornos mentais relacionados ao trabalho são de notificação compulsória apenas em casos que envolvam violência física contra trabalhadores.","a notificação compulsória dos transtornos mentais relacionados ao trabalho no Sistema de Informação de Agravos de Notificação (Sinan) tem caráter epidemiológico e visa orientar intervenções no ambiente laboral.","a notificação dos casos confirmados de transtornos mentais relacionados ao trabalho é feita exclusivamente para atender exigências legais.","a confirmação da relação entre transtornos mentais e o trabalho só é válida se realizada por inspeção direta do ambiente laboral.","o afastamento do trabalhador é obrigatório em todos os casos de transtornos mentais relacionados ao trabalho, independentemente da gravidade dos sintomas."],"correta":"B"},{"numero":53,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Um trabalhador apresenta sinais de desidratação tais como diminuição do volume urinário e urina de coloração escura. O técnico de enfermagem do trabalho deve estar ciente do papel dos rins no equilíbrio hídrico. Acerca do tema, avalie as afirmativas a seg uir e escolha a que corretamente descreve como os rins contribuem para a manutenção desse equilíbrio.","alternativas":["Os rins eliminam exclusivamente a água excedente, mantendo os níveis de sódio constantes.","Os rins filtram todo o sangue do corpo uma vez ao dia para eliminar toxinas e reabsorver água.","Os rins regulam o volume de água no corpo ajustando a reabsorção de água nos túbulos renais em resposta ao hormônio antidiurético (ADH).","Os rins produzem urina concentrada apenas quando o corpo está em estado de hiper-hidratação.","Os rins eliminam eletrólitos do corpo em maior quantidade que a água para manter a osmolaridade"],"correta":"C"},{"numero":54,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Com base na Norma Regulamentadora NR-32 - Segurança e Saúde no Trabalho em Serviços de Saúde (atualizada 2022), uma ação correta em relação à prevenção de acidentes envolvendo materiais perfurocortantes é","alternativas":["reencapar agulhas com cuidado, utilizando técnica manual segura, para evitar acidentes.","desconectar manualmente agulhas das seringas para facilitar o descarte adequado.","encaminhar materiais perfurocortantes a um setor específico somente ao final do turno de trabalho.","descartar materiais perfurocortantes diretamente no lixo comum para reduzir custos com descarte especializado.","utilizar recipientes apropriados para descarte de perfurocortantes e localizá -los em suporte exclusivo e em altura visível"],"correta":"E"},{"numero":55,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Um trabalhador da construção civil apresenta um ferimento cortante na mão direita, causado por um objeto metálico enferrujado. Durante o atendimento no ambulatório da empresa, o trabalhador informou que recebeu a última dose da vacina antitetânica há 15 anos. A conduta correta a ser tomada pelo técnico de enfermagem do trabalho nesse caso é","alternativas":["realizar a limpeza do f erimento com solução fisiológica, notificar o caso ao médico do trabalho e encaminhar o trabalhador para atualização da vacina antitetânica.","realizar a limpeza do ferimento com hipoclorito de sódio a 0,1% para desinfecção da ferida e encaminhar o traba lhador para atualização da vacina antitetânica.","realizar a limpeza do ferimento com solução fisiológica e liberar o trabalhador para voltar ao trabalho.","realizar a limpeza do ferimento com solução fisiológica, aplicar um antibiótico tópico na ferida e encaminhar o trabalhador para atualização da vacina antitetânica.","realizar a limpeza do ferimento com solução fisiológica, aplicar óleo à base de ácidos graxos essenciais (AGEs) na ferida e liberar o trabalhador para voltar ao trabalho"],"correta":"A"},{"numero":56,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"As dermatoses ocupacionais são alterações na pele, mucosa e anexos relacionadas ao ambiente e processos de trabalho. Sobre as características e a vigilância das dermatoses ocupacionais, avalie as afirmativas a seguir e assinale (V) para a ver dadeira e (F) para a falsa. ( ) As dermatoses ocupacionais são exclusivamente causadas por agentes químicos presentes no ambiente de trabalho. ( ) A notificação de dermatoses ocupacionais no Sinan (Sistema de Informações de Agravos de Notificação) dev e ser realizada somente em casos graves que causem incapacidade para o trabalho. ( ) As manifestações clínicas das dermatoses ocupacionais se limitam a eritema e edema, sem apresentar complicações secundárias. ( ) As dermatoses ocupacionais podem ocor rer quando as atividades profissionais desenvolvidas, as condições de trabalho, o uso inadequado ou a falta de Equipamentos de Proteção Individual (EPI) expõem o trabalhador a agentes químicos, físicos, biológicos ou psicossociais. As afirmativas são, respectivamente,","alternativas":["V – F – F – V.","F – F – F – V.","V – V – F – F.","V – V – V – F.","F – F – V – V"],"correta":"B"},{"numero":57,"disciplina":"Enfermagem","assunto":"Hipertensão Arterial","enunciado":"A Pressão Arterial (PA) refere -se à pressão exercida pelo sangue contra as paredes das artérias. Em relação ao tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A pressão sistólica é a pressão mais alta gerada pelo coração, durante a contração do ventrículo esquerdo. ( ) A pressão diastólica é a pressão mais baixa gerada pelo coração, durante o relaxamento do ventrículo esquerdo. ( ) A pressão sistólica é a pressão mais baixa gerada pelo coração, durante a contração do ventrículo esquerdo. ( ) A pressão diastólica é a pressão mais alta gerada pelo coração, durante o relaxamento do ventrículo esquerdo. As afirmativas são, respectivamente,","alternativas":["V – F – F – V.","F – V – F – V.","V – V – F – F.","V – V – V – F.","F – F – V – V."],"correta":"C"},{"numero":58,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Para um paciente com diabetes mellitus, a prescrição médica para a administração de insulina é de 14 unidades de insulina regular (R) e 18 unidades de insulina NPH, ambas a serem administradas na mesma seringa, antes do café da manhã. Considerando as boas práticas de preparo e administração de insulina, as etapas que descrevem corretamente o procedimento para a aspiração das doses são:","alternativas":["higienizar as mãos, aspirar primeiro 18 unidades de insulina NPH, depois 14 unidades de insulina regular, evitando misturar as soluções no frasco.","higienizar as mãos, aspirar 14 unidades de insulina regular primeiro, depois 18 unidades de insulina NPH, evitando misturar as soluções no frasco.","higienizar as mãos, homoge neizar o frasco da insulina NPH, aspirar primeiro 14 unidades de insulina regular e, em seguida, 18 unidades de insulina NPH.","higienizar as mãos, homogeneizar o frasco da insulina NPH, aspirar primeiro 18 unidades de insulina NPH, depois 14 unidades de insulina regular.","higienizar as mãos, misturar a insulina NPH agitando o frasco vigorosamente, aspirar primeiro 18 unidades de insulina NPH e, depois, 14 unidades de insulina regular"],"correta":"C"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Um trabalhador do setor de saúde foi exposto ac identalmente a sangue potencialmente contaminado durante a manipulação de materiais perfurocortantes. O técnico de enfermagem do trabalho deve seguir os protocolos de prevenção de doenças infecciosas. A ação adequada a ser tomada imediatamente após a exposição é","alternativas":["lavar o local da exposição com hipoclorito a 1% para desinfetar rapidamente a área.","encaminhar o trabalhador para exames laboratoriais apenas se apresentar sinais clínicos de infecção após a exposição.","aplicar um antisséptico à base de c lorexidina e aguardar 24 horas antes de relatar o incidente, caso não surjam sintomas.","lavar o local com água e sabão e notificar o incidente ao serviço de saúde ocupacional para avaliação e seguimento.","iniciar profilaxia pós-exposição (PPE) somente após a confirmação laboratorial de que o material estava contaminado"],"correta":"D"},{"numero":60,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Um técnico de enfermagem do trabalho está acompanhando um trabalhador que apresentou febre, cefaleia, mialgia e fadiga após retorno de uma viagem a uma região endêmica de febre amarela. A ação correta a ser realizada pelo técnico de enfermagem nesse caso é","alternativas":["administrar antitérmicos e liberar o trabalhador para retornar às atividades enquanto monitora os sintomas.","encaminhar o trabalha dor para isolamento domiciliar, recomendando repouso e hidratação sem necessidade de exames.","registrar os sintomas no prontuário e orientar o uso de Equipamentos de Proteção Individual (EPIs).","solicitar diretamente a vacinação contra febre amarela para evitar a evolução da doença e liberar o trabalhador para atividades.","encaminhar o trabalhador para avaliação médica imediata e notificar o caso à Vigilância Epidemiológica, considerando a possibilidade de doença infecciosa de notificação compulsória."],"correta":"E"}]}] as const;
export async function sincronizarFGVEBserhTecnicos2025() {
 const usuario=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!usuario)return {inseridas:0,existentes:0,repetidas:0};
 const normalizar=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const registros=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const jaConhecidos=new Set(registros.map(q=>normalizar(q.enunciado)));
 const disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,repetidas=0;
 for(const lote of LOTES)for(const q of lote.itens){
  if(!q.enunciado.trim()||q.alternativas.length!==5||q.alternativas.some(a=>!a.trim())||
   !["A","B","C","D","E"].includes(q.correta)||new Set(q.alternativas.map(a=>a.trim().toLowerCase())).size!==5)
   throw new Error("[ebserh-tecnicos-2025] Item inválido: "+lote.id+"-"+q.numero);
  const origemId="fgv-"+lote.id+"-tipo1-q"+String(q.numero).padStart(2,"0");
  if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
  const hash=normalizar(q.enunciado);if(jaConhecidos.has(hash)){repetidas++;continue;}
  let disciplinaId=disciplinas.get(q.disciplina);
  if(!disciplinaId){
   let d=await prisma.disciplina.findFirst({where:{usuarioId:usuario.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
   if(!d)d=await prisma.disciplina.create({data:{usuarioId:usuario.id,nome:q.disciplina},select:{id:true}});
   disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
  }
  await prisma.questao.create({data:{
    usuarioId:usuario.id,disciplinaId,tema:q.assunto,fonte:FONTE_PROVAS_REAIS,origemId,
    banca:"FGV",ano:2025,dificuldade:"medio",orgao:"Empresa Brasileira de Serviços Hospitalares — EBSERH",cargo:lote.cargo,
    fonteUrl:lote.prova,enunciado:q.enunciado,
    explicacao:"FGV/EBSERH 2025, "+lote.cargo+", questão "+q.numero+
      ". Gabarito definitivo: alternativa "+q.correta+". Prova: "+lote.prova+" | Gabarito: "+lote.gabarito,
    alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
  }});
  inseridas++;jaConhecidos.add(hash);
 }
 console.log("[ebserh-tecnicos-2025] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" duplicadas ignoradas.");
 return {inseridas,existentes,repetidas};
}
